from pathlib import Path
import json,hashlib
root=Path(__file__).resolve().parent
timeline=json.loads((root/'game-timeline.json').read_text())
html='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>조약돌 요요 · 모션 검토</title>
<style>body{background:#101f28;color:#e7f7f2;font:16px system-ui,sans-serif;margin:24px}h1{font-size:26px;margin:0 0 10px}p{color:#b8d2d7;line-height:1.5}header{max-width:1000px;margin:auto}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(520px,1fr));gap:20px;max-width:1360px;margin:20px auto}article{padding:16px;background:#19313c;border:1px solid #39616a;border-radius:16px}h2{margin:0 0 10px;font-size:21px}canvas{background:linear-gradient(#234d5b,#163337);width:100%;border-radius:10px}button,select,input{font:inherit;margin:4px;padding:7px 12px}button,select{background:#d9f4e7;color:#102b32;border:0;border-radius:8px}a{color:#9debd7}small{display:block;color:#b6d8d1;margin:8px 0}.row{display:flex;align-items:center;flex-wrap:wrap}.ref{height:160px}.badge{color:#ffe2a3}</style>
<header><h1>조약돌 요요 · 네 가지 사용 모션</h1><p class="badge">검토 후보 · 아직 게임 모션으로 등록하지 않았습니다.</p><p>게임의 전투·캐릭터 표시 코드를 실행해 기록한 프레임과 요요 위치를 재생합니다. 준비 → 발사 → 회수 → 마무리 순서이며 실제 판정은 발사 중 본체에만 있습니다. 아래 배경·실은 검토용 재현입니다. 화면 캡처나 Android 기기 검증 자료는 아닙니다.</p><p><a href="qa-motion-r02/trace-normal.mp4">정상 재생 영상</a> · <a href="qa-motion-r02/trace-slow.mp4">느린 재생 영상</a> · <a href="qa-motion-r02/trace-normal-flip.mp4">좌우 반전 영상</a></p><div class="row"><button id="play">일시정지</button><select id="speed"><option value="1">정상 속도</option><option value="0.25">느린 재생 0.25×</option></select><button id="all">전체 프레임 보기</button></div></header><main class="grid" id="grid"></main>
<script>const data=TIMELINE;const approved=APPROVED;const sources={};for(const t of data.motions){const im=new Image();im.src="motions/"+t.character+"/"+t.mode+"/r02/sheet-128.png";sources[t.character+"/"+t.motion_id]={im,columns:t.metadata.columns};}for(const t of approved){const im=new Image();im.src="../../"+t.path;sources[t.character_id+"/"+t.visual_state_id]={im,columns:t.atlas_columns||16};}let playing=true,speed=1,elapsed=0,last=performance.now();const cards=[];const body=new Image();body.src='../../forest_arena/assets/common/accessory/pebble_yoyo_combat.png';
for(const t of data.motions){const title=(t.character==='ja-hyun'?'자현':'나비')+' · '+(t.mode==='ground'?'지상':'공중');const dir='motions/'+t.character+'/'+t.mode+'/r02/';const a=document.createElement('article');a.innerHTML='<h2>'+title+'</h2><canvas width="640" height="330"></canvas><div class="row"><label><input type="checkbox">좌우 반전</label><label>프레임 <input type="range" min="0" max="15" value="0"></label></div><small></small><div class="contact" hidden><a href="'+dir+'contact.png" target="_blank">전체 16프레임 비교판</a><img width="100%" src="'+dir+'contact.png"></div><details><summary>승인 참조와 크기 확인</summary><img class="ref" src="../../assets/character/'+t.character+'/reference/v01/combat.png"><p>모션 전체 공통 배율 '+t.metadata.common_scale+' · 표시 배율 '+t.metadata.presentation_scale+' · 발 기준120px. 프레임마다 크기를 바꾸지 않았습니다.</p></details>';document.querySelector('#grid').append(a);const im=new Image();im.src=dir+'sheet-128.png';const c={t,im,a,canvas:a.querySelector('canvas'),flip:a.querySelector('[type=checkbox]'),range:a.querySelector('[type=range]'),status:a.querySelector('small'),manual:null};c.range.oninput=()=>{playing=false;document.querySelector('#play').textContent='재생';c.manual=Number(c.range.value);};cards.push(c);}
function draw(c,dt){const ctx=c.canvas.getContext('2d');ctx.clearRect(0,0,640,330);let index=Math.floor(elapsed*60)%80;let r=c.t.frames[Math.min(index,48)];if(c.manual!==null)r=c.t.frames.find(f=>f.frame===c.manual&&f.phase!=='idle')||r;const phase={startup:'준비',extend:'발사',return:'회수',recovery:'마무리',idle:'대기'}[r.phase];c.status.textContent=phase+' · '+(r.frame+1)+'/16 · '+r.tick+'틱 · 원본 확인값 '+c.t.metadata.sheet_sha256.slice(0,12);if(playing)c.range.value=r.frame;ctx.save();ctx.translate(c.flip.checked?450:190,230);ctx.scale(c.flip.checked?-1.5:1.5,1.5);if(c.t.mode==='ground'){ctx.strokeStyle='#678f83';ctx.beginPath();ctx.moveTo(-120,14);ctx.lineTo(220,14);ctx.stroke();}let tx=r.rendered_tip_x??r.tip_x,ty=r.rendered_tip_y??r.tip_y;if(['startup','recovery'].includes(r.phase)){tx=r.hand_x;ty=r.hand_y;}if(r.phase!=="idle"){ctx.strokeStyle='#fff0ca';ctx.lineWidth=1.8;ctx.beginPath();ctx.moveTo(r.hand_x,r.hand_y);ctx.lineTo(tx,ty);ctx.stroke();}const source=sources[c.t.character+"/"+r.motion];if(source?.im.complete)ctx.drawImage(source.im,(r.frame%source.columns)*128,Math.floor(r.frame/source.columns)*128,128,128,r.sprite_x-64*r.scale,r.sprite_y-64*r.scale,128*r.scale,128*r.scale);if((r.phase!=="idle")&&body.complete){ctx.save();ctx.translate(tx,ty);ctx.rotate(r.tick*.5);ctx.drawImage(body,-14,-14,28,28);ctx.restore();}ctx.restore();}
function loop(now){const dt=(now-last)/1000;last=now;if(playing)elapsed+=dt*speed;for(const c of cards)draw(c,dt);requestAnimationFrame(loop);}requestAnimationFrame(loop);document.querySelector('#play').onclick=()=>{playing=!playing;for(const c of cards)c.manual=null;document.querySelector('#play').textContent=playing?'일시정지':'재생';};document.querySelector('#speed').onchange=e=>speed=Number(e.target.value);document.querySelector('#all').onclick=()=>{for(const c of cards)c.a.querySelector('.contact').hidden=!c.a.querySelector('.contact').hidden;};
</script>'''
manifest=json.loads((root.parents[1]/'assets/character/manifest.json').read_text())
approved=[r for r in manifest['assets'] if r.get('type')=='animation-runtime' and r.get('visual_state_id') in ['idle','jump'] and r.get('character_id') in ['ja-hyun','nabi']]
(root/'index.html').write_text(html.replace('TIMELINE',json.dumps(timeline,ensure_ascii=False)).replace('APPROVED',json.dumps(approved,ensure_ascii=False)))
print('Created candidate review page with actual49-tick timelines for4 motions.')
